// src/middleware/auth.js
'use strict';

const { query } = require('../db');
const { toUser } = require('../lib/serialize');

const GUEST_PREFIX = 'guest:';

/** Reads `Authorization: Bearer <token>`. */
function bearerToken(req) {
  const header = req.get('authorization');
  if (!header) return null;

  const match = /^Bearer\s+(.+)$/i.exec(header.trim());
  return match ? match[1].trim() : null;
}

/**
 * Guests get a random key generated by the browser and stored locally. It
 * scopes their bookings to that browser exactly like the old localStorage
 * version did, without letting one visitor read another's orders.
 */
function guestKey(req) {
  const raw = req.get('x-guest-key');
  if (typeof raw !== 'string') return null;

  const trimmed = raw.trim();
  if (!trimmed || trimmed.length > 120) return null;
  return trimmed;
}

/** Populates req.user (or null) and req.guestKey on every request. */
async function attachUser(req, _res, next) {
  req.user = null;
  req.guestKey = guestKey(req);

  const token = bearerToken(req);
  if (!token) return next();

  try {
    const { rows } = await query(
      `SELECT u.*
         FROM sessions s
         JOIN users u ON u.id = s.user_id
        WHERE s.token = $1
          AND s.expires_at > now()
          AND u.is_active = true`,
      [token]
    );

    if (rows[0]) {
      req.user = toUser(rows[0]);
      req.sessionToken = token;
    }

    return next();
  } catch (error) {
    return next(error);
  }
}

/** Rejects the request unless a valid session was supplied. */
function requireUser(req, res, next) {
  if (!req.user) {
    return res.status(401).json({ error: 'Please sign in to continue' });
  }
  return next();
}

/**
 * The key that owns a booking: the account's email, or the guest key of the
 * browser that placed it. Returns null when a guest request carries no key,
 * which the caller turns into a 400.
 */
function ownerKeyFor(req) {
  if (req.user) return req.user.email;
  if (req.guestKey) return `${GUEST_PREFIX}${req.guestKey}`;
  return null;
}

/** Hands a browser's pre-sign-in bookings over to the account signing in. */
async function claimGuestOrders(userId, email, key) {
  if (!key) return 0;

  const { rowCount } = await query(
    `UPDATE orders
        SET user_id = $1, owner_key = $2
      WHERE owner_key = $3`,
    [userId, email, `${GUEST_PREFIX}${key}`]
  );

  return rowCount;
}

/** Rejects unless a signed-in admin user. */
function requireAdmin(req, res, next) {
  if (!req.user) {
    return res.status(401).json({ error: 'Please sign in to continue' });
  }
  if (req.user.userType !== 'admin') {
    return res.status(403).json({ error: 'Admin access required' });
  }
  return next();
}

module.exports = {
  GUEST_PREFIX,
  attachUser,
  requireUser,
  requireAdmin,
  ownerKeyFor,
  claimGuestOrders,
  bearerToken,
  guestKey
};
